174	    var createTime = extractOrderTime(orderCell);
175	    if (!createTime) {
176	      // 次选：整行里仅相对时间（分钟前/今天/星期），仍禁止绝对「截止」日
177	      var blobForTime = cells.join(' ');
178	      var relOnly = cleanText(blobForTime)
179	        .replace(/\b57\d{16}\b/g, ' ')
180	        .replace(/\b\d{15,20}\b/g, ' ');
181	      var rm =
182	        relOnly.match(/(\d+\s*分钟前)/) ||
183	        relOnly.match(/(\d+\s*小时前)/) ||
184	        relOnly.match(/(\d+\s*天前)/) ||
185	        relOnly.match(/(昨天\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
186	        relOnly.match(/(今天\s*\d{1,2}:\d{2}(?::\d{2})?)/) ||
187	        relOnly.match(/((?:星期|周)[一二三四五六日天]\s*\d{1,2}:\d{2}(?::\d{2})?)/);
188	      if (rm) createTime = cleanText(rm[1]);
189	    }
190	    var productCell = get('productName') || '';
191	    var quantity = extractQty(productCell);
192	    if (quantity == null) quantity = extractQty(cells.join(' ')) || 0;
193	    var productName = productCell || '';
194	    var payRaw = get('payAmount') || '';
195	    var payAmount = parseNumber(payRaw);
196	    var status = get('orderStatus') || '';
197	    var shipping = get('shippingMethod') || get('shippingOption') || '';
198	    var buyer = get('buyer') || '';
199	    var blob = cells.join(' ');
200	
201	    return {
202	      orderId: orderId,
203	      orderStatus: status,
204	      payTime: '',
205	      createTime: createTime,
206	      createTimeRaw: orderCell.slice(0, 80),
207	      productName: productName,
208	      sellerSku: '',
209	      skuId: '',
210	      quantity: quantity,
211	      payAmount: payAmount != null ? payAmount : 0,
212	      shippingStatus: shipping,
213	      buyerRegion: '',
214	      buyer: buyer,
215	      currencyHint: detectCurrency(payRaw) || detectCurrency(blob),
216	      rawCells: cells.slice(0, 10)
217	    };
218	  }
219	
220	  function parseHtmlTable(table) {
221	    var trs = Array.prototype.slice.call(table.querySelectorAll('tr'));
222	    if (trs.length < 1) return { rows: [], headers: [], colMap: {} };
223	    var headIdx = -1;
224	    var i;
225	    for (i = 0; i < Math.min(3, trs.length); i++) {
226	      var cells = Array.prototype.slice.call(trs[i].querySelectorAll('th,td')).map(function (c) {
227	        return cleanText(c.textContent);
228	      });
229	      var hits = 0;
230	      for (var hi = 0; hi < cells.length; hi++) if (matchField(cells[hi])) hits++;
231	      var hasOid = false;
232	      for (var oi = 0; oi < cells.length; oi++) if (extractOrderId(cells[oi])) hasOid = true;
233	      if (hits >= 2 && !hasOid) {
234	        headIdx = i;
235	        break;
236	      }
237	    }
238	    var colMap = {};
239	    var headCells = [];
240	    if (headIdx >= 0) {
241	      headCells = Array.prototype.slice.call(trs[headIdx].querySelectorAll('th,td')).map(function (c) {
242	        return cleanText(c.textContent);
243	      });
244	      headCells.forEach(function (h, idx) {
245	        var f = matchField(h);
246	        if (f && colMap[f] == null) colMap[f] = idx;
247	      });
248	    }
249	    var def = defaultColMap();
250	    Object.keys(def).forEach(function (k) {
251	      if (colMap[k] == null) colMap[k] = def[k];
252	    });
253	    if (!headCells.length) headCells = ['', '订单', '客户', '商品', '订单状态', '物流方式', '物流选项', '合计'];
254	
255	    var rows = [];
256	    var seen = {};
257	    var start = headIdx >= 0 ? headIdx + 1 : 0;
258	    for (var r = start; r < trs.length; r++) {
259	      var row = parseRow(trs[r], colMap);
260	      if (!row || seen[row.orderId]) continue;
261	      seen[row.orderId] = true;
262	      rows.push(row);
263	    }
264	    return { colMap: colMap, rows: rows, headers: headCells };
265	  }
266	
267	  function parseOrderIdNodes() {
268	    var nodes = Array.prototype.slice.call(document.querySelectorAll('.order_id_number, [class*="order_id"]'));
269	    if (!nodes.length) return null;
270	    var rows = [];
271	    var seen = {};
272	    var colMap = defaultColMap();
273	    for (var i = 0; i < nodes.length; i++) {
274	      var n = nodes[i];
275	      var orderId = extractOrderId(n.textContent);
276	      if (!orderId || seen[orderId]) continue;
277	      seen[orderId] = true;
278	      var tr = n.closest('tr');
279	      if (tr) {
280	        var row = parseRow(tr, colMap);
281	        if (row) {
282	          rows.push(row);
283	          continue;
284	        }
285	      }
286	      var text = cleanText((tr || n).textContent).slice(0, 400);
287	      var payM = text.match(/[£$€]\s*([0-9]+(?:\.[0-9]+)?)/);
288	      var quantity = extractQty(text) || 0;
289	      var status = '';
290	      var sm = text.match(/(等待中|等待打包|待揽收|已发货|已完成|已取消|待发货|运输中)/);
291	      if (sm) status = sm[1];
292	      rows.push({
293	        orderId: orderId,
294	        orderStatus: status,
295	        payTime: '',
296	        createTime: extractOrderTime(text),
297	        createTimeRaw: text.slice(0, 80),
298	        productName: '',
299	        sellerSku: '',
300	        skuId: '',
301	        quantity: quantity,
302	        payAmount: payM ? parseNumber(payM[0]) : 0,
303	        shippingStatus: '',
304	        buyerRegion: '',
305	        buyer: '',
306	        currencyHint: detectCurrency(text),
307	        rawCells: [text.slice(0, 160)]
308	      });
309	    }
310	    return rows.length ? { rows: rows, headers: ['order_id_number'], colMap: {}, source: 'order-id-nodes' } : null;
311	  }
312	
313	  try {
314	    var url = location.href || '';
315	    var title = document.title || '';
316	    var parsed = null;
317	    var source = 'none';
318	    var table = pickBestTable();
319	    if (table) {
320	      parsed = parseHtmlTable(table);
321	      source = 'html-table';
322	    }
323	    if (!parsed || !parsed.rows || parsed.rows.length === 0) {
324	      var fb = parseOrderIdNodes();
325	      if (fb) {
326	        parsed = fb;
327	        source = fb.source || 'order-id-nodes';
328	      }
329	    }
330	
331	    var rows = parsed && parsed.rows ? parsed.rows : [];
332	    var currencyHits = { USD: 0, GBP: 0, EUR: 0, CNY: 0 };
333	    for (var ri = 0; ri < rows.length; ri++) {
334	      var c = rows[ri].currencyHint;
335	      if (c && currencyHits[c] != null) currencyHits[c]++;
336	    }
337	    var currency = 'GBP';
338	    var max = -1;
339	    var keys = Object.keys(currencyHits);
340	    for (var ki = 0; ki < keys.length; ki++) {
341	      var k = keys[ki];
342	      if (currencyHits[k] > max) {
343	        max = currencyHits[k];
344	        currency = k;
345	      }
346	    }
347	    if (max <= 0) currency = 'GBP';
348	
349	    var ok = rows.length > 0;
350	    return JSON.stringify({
351	      ok: ok,
352	      source: source,
353	      module: 'orders',
354	      url: url,
355	      title: title,
356	      currency: currency,
357	      currencyHits: currencyHits,
358	      headers: parsed && parsed.headers ? parsed.headers : [],
359	      colMap: parsed && parsed.colMap ? parsed.colMap : {},
360	      rows: rows,
361	      rowCount: rows.length,
362	      error: ok ? null : 'no order table. url=' + url
363	    });
364	  } catch (e) {
365	    return JSON.stringify({
366	      ok: false,
367	      source: 'none',
368	      module: 'orders',
369	      url: location.href || '',
370	      rows: [],
371	      error: String(e && e.message ? e.message : e)
372	    });
373	  }
374	})();
